382	    /**
383	     * Return the current request's {@code Idempotency-Key} header value, or {@code null} when the
384	     * header is absent/blank or there is no bound servlet request.
385	     *
386	     * @return the trimmed idempotency key, or {@code null} when none was supplied
387	     */
388	    private String currentIdempotencyKey() {
389	        org.springframework.web.context.request.RequestAttributes attributes =
390	            org.springframework.web.context.request.RequestContextHolder.getRequestAttributes();
391	        if (attributes instanceof org.springframework.web.context.request.ServletRequestAttributes servletAttributes) {
392	            String key = servletAttributes.getRequest().getHeader(IDEMPOTENCY_KEY_HEADER);
393	            if (StringUtils.hasText(key)) {
394	                return key.trim();
395	            }
396	        }
397	        return null;
398	    }
