629	    /**
630	     * Find the existing owner the given (not-yet-persisted) owner is a soft duplicate of: one that
631	     * shares the owner's last name (compared case-insensitively with collapsed whitespace) and
632	     * postcode while carrying a different normalized telephone. A blank postcode never soft-matches
633	     * (postcode is required for the match). When several owners match, the one with the lowest id is
634	     * returned so the result is deterministic; {@code null} when there is no soft match.
635	     *
636	     * @param owner the incoming owner (with normalized telephone and last name resolved)
637	     * @return the lowest-id matching existing owner, or {@code null} when none matches
638	     */
639	    private Owner findPossibleDuplicate(Owner owner) {
640	        if (!StringUtils.hasText(owner.getPostcode())) {
641	            return null;
642	        }
643	        String normalizedLastName = normalizeForComparison(owner.getLastName());
644	        String telephone = owner.getTelephone();
645	        return this.clinicService.findAllOwners().stream()
646	            .filter(existing -> normalizeForComparison(existing.getLastName()).equals(normalizedLastName)
647	                && owner.getPostcode().equals(existing.getPostcode())
648	                && !java.util.Objects.equals(telephone, existing.getTelephone()))
649	            .min(java.util.Comparator.comparing(Owner::getId))
650	            .orElse(null);
651	    }
