669	    /**
670	     * Normalize an owner address for storage: trim and collapse every internal run of whitespace to a
671	     * single space, upper-case the result and expand common street-type abbreviations token by token
672	     * ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}). A {@code null} value normalizes
673	     * to the empty string. The result is the canonical form that is stored, returned and used for every
674	     * address comparison (household duplicate detection and the shared household id).
675	     *
676	     * @param address the raw address, may be {@code null}
677	     * @return the normalized address
678	     */
679	    private String normalizeAddress(String address) {
680	        if (address == null) {
681	            return "";
682	        }
683	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
684	        if (collapsed.isEmpty()) {
685	            return "";
686	        }
687	        String[] tokens = collapsed.split(" ");
688	        StringBuilder sb = new StringBuilder(collapsed.length());
689	        for (int i = 0; i < tokens.length; i++) {
690	            if (i > 0) {
691	                sb.append(' ');
692	            }
693	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
694	        }
695	        return sb.toString();
696	    }
697	
698	    /**
699	     * Normalize a value for identity comparison: trim, collapse every internal run of whitespace to a
700	     * single space and lower-case the result. A {@code null} value normalizes to the empty string.
701	     *
702	     * @param value the raw value, may be {@code null}
703	     * @return the normalized value
704	     */
705	    private String normalizeForComparison(String value) {
706	        if (value == null) {
707	            return "";
708	        }
709	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
710	    }
711	
712	    /**
713	     * Normalize an optional owner email address. A blank/absent value is treated as "not provided"
714	     * and returns {@code null}. When present, the value must be a syntactically valid address; if it
715	     * is not, an {@link InvalidRequestException} is thrown (mapped to 400 Bad Request). A valid value
716	     * is returned lower-cased.
717	     *
718	     * @param email the raw email from the request payload, may be {@code null}
719	     * @return the lower-cased email, or {@code null} when none was provided
720	     */
721	    private String normalizeEmail(String email) {
722	        if (!StringUtils.hasText(email)) {
723	            return null;
724	        }
725	        if (!EMAIL_PATTERN.matcher(email).matches()) {
726	            throw new InvalidRequestException(List.of("email"));
727	        }
728	        String lowerCased = email.toLowerCase(Locale.ROOT);
729	        // Reject an address whose domain is on the disposable-domain blocklist.
730	        String domain = lowerCased.substring(lowerCased.indexOf('@') + 1);
731	        if (DISPOSABLE_EMAIL_DOMAINS.contains(domain)) {
732	            throw new InvalidRequestException(List.of("email"));
733	        }
734	        return lowerCased;
735	    }
736	
737	    /**
738	     * Validate an optional owner postcode. A blank/absent value is treated as "not provided" and
739	     * passes (postcode is optional). When present it must be exactly four digits, and when the owner's
740	     * city has a known region (Sydney->NSW, Melbourne->VIC, Brisbane->QLD) the postcode must fall within
741	     * that region's inclusive range (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099). A city with no known
742	     * region accepts any 4-digit postcode. A violation throws an {@link InvalidRequestException} (mapped
743	     * to 400 Bad Request).
744	     *
745	     * @param city     the owner's city (used to resolve the region)
746	     * @param postcode the raw postcode from the request payload, may be {@code null}
747	     */
748	    private void validatePostcode(String city, String postcode) {
749	        if (!StringUtils.hasText(postcode)) {
750	            return;
751	        }
752	        if (!POSTCODE_PATTERN.matcher(postcode).matches()) {
753	            throw new InvalidRequestException(List.of("postcode"));
754	        }
755	        String region = CITY_REGION.get(city);
756	        int[] range = region == null ? null : REGION_POSTCODE_RANGE.get(region);
757	        if (range != null) {
758	            int value = Integer.parseInt(postcode);
759	            if (value < range[0] || value > range[1]) {
760	                throw new InvalidRequestException(List.of("postcode"));
761	            }
762	        }
763	    }
764	
765	    /**
766	     * Normalize a telephone into E.164 form. Spaces, dashes and brackets are stripped. A value that
767	     * already carries a leading '+' keeps its country code; otherwise the default country code
768	     * ({@code +61}) is assumed and a single leading '0' is dropped from the national digits. The
769	     * result must be a '+' followed by 8 to 15 digits, otherwise an {@link InvalidRequestException}
770	     * is thrown (mapped to 400 Bad Request).
771	     *
772	     * @param telephone the raw telephone from the request payload
773	     * @return the E.164 string (e.g. {@code +61412345678})
774	     */
775	    private String normalizeTelephone(String telephone) {
776	        String cleaned = TELEPHONE_SEPARATORS.matcher(telephone).replaceAll("");
777	        String candidate;
778	        if (cleaned.startsWith("+")) {
779	            candidate = cleaned;
780	        } else {
781	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
782	            candidate = "+" + DEFAULT_COUNTRY_CODE + national;
783	        }
784	        if (!E164_PATTERN.matcher(candidate).matches()) {
785	            throw new InvalidRequestException(List.of("telephone"));
786	        }
787	        // For country codes with a known fixed national-number length, reject a candidate whose
788	        // national digits (everything after the '+' and the country code) do not match that length.
789	        String digits = candidate.substring(1);
790	        for (Map.Entry<String, Integer> entry : COUNTRY_NATIONAL_LENGTH.entrySet()) {
791	            String countryCode = entry.getKey();
792	            if (digits.startsWith(countryCode)) {
793	                int nationalLength = digits.length() - countryCode.length();
794	                if (nationalLength != entry.getValue()) {
795	                    throw new InvalidRequestException(List.of("telephone"));
796	                }
797	                break;
798	            }
799	        }
800	        return candidate;
801	    }
802	
803	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
804	    @Transactional
805	    @Override
806	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
807	        Owner owner = this.clinicService.findOwnerById(ownerId);
808	        if (owner == null) {
809	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
810	        }
811	        // Soft delete: flag the owner deleted and retain the record rather than removing it. The
812	        // owner is still readable afterwards (with 'deleted' true) but is ignored by the create
813	        // endpoint's duplicate/identity checks.
814	        owner.setDeleted(true);
815	        this.clinicService.saveOwner(owner);
816	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
817	    }
818	
819	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
820	    @Override
821	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
822	        Owner owner = this.clinicService.findOwnerById(ownerId);
823	        if (owner == null) {
824	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
825	        }
826	        HttpHeaders headers = new HttpHeaders();
827	        Pet pet = petMapper.toPet(petFieldsDto);
828	        owner.setId(ownerId);
829	        pet.setOwner(owner);
830	        pet.getType().setName(null);
831	        this.clinicService.savePet(pet);
832	        PetDto petDto = petMapper.toPetDto(pet);
833	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
834	            .buildAndExpand(pet.getId()).toUri());
835	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
836	    }
837	
838	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
839	    @Override
840	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
841	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
842	        if (currentOwner != null) {
843	            Pet currentPet = this.clinicService.findPetById(petId);
844	            if (currentPet != null) {
845	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
846	                currentPet.setName(petFieldsDto.getName());
847	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
848	                this.clinicService.savePet(currentPet);
849	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
850	            }
851	        }
852	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
853	    }
854	
855	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
856	    @Override
857	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
858	        HttpHeaders headers = new HttpHeaders();
859	        Visit visit = visitMapper.toVisit(visitFieldsDto);
860	        Pet pet = new Pet();
861	        pet.setId(petId);
862	        visit.setPet(pet);
863	        this.clinicService.saveVisit(visit);
864	        VisitDto visitDto = visitMapper.toVisitDto(visit);
865	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
866	            .buildAndExpand(visit.getId()).toUri());
867	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
868	    }
869	
870	
871	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
872	    @Override
873	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
874	        Owner owner = this.clinicService.findOwnerById(ownerId);
875	        if (owner != null) {
876	            Pet pet = owner.getPet(petId);
877	            if (pet != null) {
878	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
879	            }
880	        }
881	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
882	    }
883	}
